import{_ as s,o as n,c as e,ai as t}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"HRM 人力资源管理系统","description":"","frontmatter":{},"headers":[],"relativePath":"instances/office/hrm.md","filePath":"instances/office/hrm.md"}'),r={name:"instances/office/hrm.md"};function i(l,a,p,d,c,h){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="hrm-人力资源管理系统" tabindex="-1">HRM 人力资源管理系统 <a class="header-anchor" href="#hrm-人力资源管理系统" aria-label="Permalink to “HRM 人力资源管理系统”">​</a></h1><blockquote><p>📋 规划中（功能设计已覆盖约 60%） · 所属模块：<a href="/my-vitepress-site/instances/office/">04 办公自动化</a> · 模块优先级：第 1 位 替换说明：本页取代原「在线表单与数据收集系统」——表单是能力不是系统，已并入 <a href="/my-vitepress-site/instances/office/bpm.html">BPM</a> 作为内置表单引擎。</p></blockquote><h2 id="📌-项目简介" tabindex="-1">📌 项目简介 <a class="header-anchor" href="#📌-项目简介" aria-label="Permalink to “📌 项目简介”">​</a></h2><p>HRM（Human Resource Management）覆盖员工<strong>「入转调离 + 考勤 + 薪酬 + 招聘 + 绩效」</strong>的全生命周期，是企业里<strong>全员高频</strong>的独立系统。它不重复造流程与表单，而是复用 <a href="/my-vitepress-site/instances/office/bpm.html">BPM</a> 的审批引擎与内置表单能力，把人事事务沉淀为结构化数据。</p><ul><li><strong>面向用户</strong>：HR（人事专员 / 主管）、员工（考勤 / 请假 / 工资条）、管理者（绩效 / 编制 / 人力成本）</li><li><strong>核心价值</strong>：把散落在 Excel、纸质单、群聊里的人事事务，变成可查询、可审批、可统计的结构化数据</li><li><strong>为什么替换「在线表单」</strong>：表单只是 BPM 的输入组件，而 HRM 是真正的独立系统且全员使用 —— 用它补齐办公模块的完整度更有价值</li></ul><h2 id="🗺️-功能规划-覆盖约-60" tabindex="-1">🗺️ 功能规划（覆盖约 60%） <a class="header-anchor" href="#🗺️-功能规划-覆盖约-60" aria-label="Permalink to “🗺️ 功能规划（覆盖约 60%）”">​</a></h2><blockquote><p>按标准 HRM 约 10 个模块估算，本期覆盖 <strong>6 个核心模块 ≈ 60%</strong>；剩余约 40% 列入后续扩展。</p></blockquote><h3 id="🧩-本期核心-6-个模块-约-60" tabindex="-1">🧩 本期核心（6 个模块，约 60%） <a class="header-anchor" href="#🧩-本期核心-6-个模块-约-60" aria-label="Permalink to “🧩 本期核心（6 个模块，约 60%）”">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>关键能力</th></tr></thead><tbody><tr><td>组织架构</td><td>部门树、岗位、编制、汇报关系</td></tr><tr><td>员工档案</td><td>入职 / 转正 / 调岗 / 离职、劳动合同、证照</td></tr><tr><td>考勤管理</td><td>打卡、排班、请假、加班、出差</td></tr><tr><td>薪酬管理</td><td>工资核算、社保公积金、个税、工资条</td></tr><tr><td>招聘管理</td><td>职位发布、简历库、面试安排、Offer</td></tr><tr><td>绩效管理</td><td>目标设定、考核评分、结果分布</td></tr></tbody></table><h3 id="📋-后续扩展-剩余约-40" tabindex="-1">📋 后续扩展（剩余约 40%） <a class="header-anchor" href="#📋-后续扩展-剩余约-40" aria-label="Permalink to “📋 后续扩展（剩余约 40%）”">​</a></h3><ul><li>[ ] 培训管理（课程 / 报名 / 学时）</li><li>[ ] 员工自助（自助查询 / 申请 / 证明开具）</li><li>[ ] 报表分析（人力成本、流动率、编制使用率）</li><li>[ ] 组织编制与人才盘点</li><li>[ ] 移动端 / 企业微信 · 钉钉集成</li></ul><h2 id="🏗️-技术架构" tabindex="-1">🏗️ 技术架构 <a class="header-anchor" href="#🏗️-技术架构" aria-label="Permalink to “🏗️ 技术架构”">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│   表现层：Vue 3 + TypeScript（HR 工作台 / 员工自助）      │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│   HRM 应用层                                            │</span></span>
<span class="line"><span>│   组织架构 · 员工档案 · 考勤 · 薪酬 · 招聘 · 绩效          │</span></span>
<span class="line"><span>├───────────────────┬──────────────────────────────────┤</span></span>
<span class="line"><span>│   审批 / 流程       │   表单引擎（复用 BPM 内置）          │</span></span>
<span class="line"><span>│   （BPM 流程引擎）   │   JSON Schema 动态渲染 / 校验       │</span></span>
<span class="line"><span>├───────────────────┴──────────────────────────────────┤</span></span>
<span class="line"><span>│   OpenBiz 底座：多租户 / 权限 / 状态机 / 消息通知         │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│   数据层：MySQL 8（组织 / 员工 / 考勤 / 薪酬 / 招聘 / 绩效）│</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><ul><li><strong>HRM 是「业务组装层」</strong>：组织、档案、考勤、薪酬是 HRM 自有领域；请假、加班、调岗、Offer 审批委托给 BPM。</li><li>所有能力跑在 OpenBiz 底座上，天然具备多租户、权限与状态机。</li></ul><h2 id="🧰-技术栈-开发语言" tabindex="-1">🧰 技术栈 / 开发语言 <a class="header-anchor" href="#🧰-技术栈-开发语言" aria-label="Permalink to “🧰 技术栈 / 开发语言”">​</a></h2><table tabindex="0"><thead><tr><th>分层</th><th>技术</th></tr></thead><tbody><tr><td>前端</td><td>Vue 3 + TypeScript + Vite</td></tr><tr><td>后端</td><td>Java 21 + Spring Boot 3</td></tr><tr><td>数据库</td><td>MySQL 8</td></tr><tr><td>底座</td><td>OpenBiz（多租户 / 权限 / 状态机 / 动态表单）</td></tr><tr><td>复用</td><td>BPM 流程引擎（审批）、内置表单引擎</td></tr><tr><td>集成</td><td>REST API + Webhook 消息通知</td></tr></tbody></table><h2 id="📂-目录结构-规划" tabindex="-1">📂 目录结构（规划） <a class="header-anchor" href="#📂-目录结构-规划" aria-label="Permalink to “📂 目录结构（规划）”">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hrm/</span></span>
<span class="line"><span>├── web/                  # Vue 3（组织 / 档案 / 考勤 / 薪酬 / 招聘 / 绩效）</span></span>
<span class="line"><span>├── server/</span></span>
<span class="line"><span>│   ├── org/              # 组织架构、岗位、编制</span></span>
<span class="line"><span>│   ├── employee/         # 员工档案、入转调离、合同</span></span>
<span class="line"><span>│   ├── attendance/       # 考勤、排班、请假加班（接 BPM）</span></span>
<span class="line"><span>│   ├── payroll/          # 工资核算、社保、个税、工资条</span></span>
<span class="line"><span>│   ├── recruit/          # 招聘、简历、面试、Offer</span></span>
<span class="line"><span>│   └── performance/      # 目标、考核、评分</span></span>
<span class="line"><span>└── docs/                 # 本文档</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="🚀-开发路线" tabindex="-1">🚀 开发路线 <a class="header-anchor" href="#🚀-开发路线" aria-label="Permalink to “🚀 开发路线”">​</a></h2><table tabindex="0"><thead><tr><th>里程碑</th><th>内容</th><th>覆盖</th></tr></thead><tbody><tr><td>M1</td><td>组织架构 + 员工档案</td><td>约 20%</td></tr><tr><td>M2</td><td>考勤 + 请假加班（接 BPM 审批）</td><td>约 40%</td></tr><tr><td>M3</td><td>薪酬核算 + 工资条</td><td>约 50%</td></tr><tr><td>M4</td><td>招聘 + 绩效</td><td><strong>约 60%</strong></td></tr><tr><td>M5</td><td>培训 / 自助 / 报表 / 移动端</td><td>剩余 40%</td></tr></tbody></table><blockquote><p>达到「最小可运行闭环」后状态更新为 🔧 验证中 / 在建；测试与运行证据齐备后更新为 ✅ 已验证。</p></blockquote><h2 id="🔗-相关资源" tabindex="-1">🔗 相关资源 <a class="header-anchor" href="#🔗-相关资源" aria-label="Permalink to “🔗 相关资源”">​</a></h2><ul><li>流程底座：<a href="/my-vitepress-site/instances/office/bpm.html">BPM 业务流程管理系统</a></li><li>协同应用：<a href="/my-vitepress-site/instances/office/oa.html">OA 办公自动化系统</a></li><li>平台内核：<a href="/my-vitepress-site/instances/platform.html">平台内核 · OpenBiz</a></li><li>技术实践：<a href="/my-vitepress-site/apps/office/">功能开发 › 办公自动化</a></li></ul><hr><p>上一级：<a href="/my-vitepress-site/instances/office/">04 办公自动化</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>`,25)])])}const m=s(r,[["render",i]]);export{o as __pageData,m as default};
